/* Straitjacket: Addressable Evidence instrument-panel design system.
   Strictly obeys straitjacket/docs/VISUAL-DESIGN.md:
   - Square corners, 1px rules, generous outer margins, tabular display figures, JetBrains Mono for evidence
   - Semantic colours only: Blue (#6F96FF), Amber (#F0B429), Red (#FF7768), Green (#63D3A4), Neutral (#8D939A)
   - No gradients, no glow, no glassmorphism, no decorative colour. */

:root {
  --bg: #0D0F12;
  --ground: #15181D;
  --surface: #15181D;
  --surface2: #1C2026;
  --ink: #ECEAE3;
  --muted: #8D939A;
  --faint: #7D848D;
  --grid: #272C33;
  --blue: #6F96FF;
  --blue-dim: #263A68;
  --amber: #F0B429;
  --amber-dim: #58451D;
  --red: #FF7768;
  --red-dim: #542925;
  --green: #63D3A4;
  --panel: rgba(13, 15, 18, 0.92);

  --sans: 'Space Grotesk Variable', 'Inter Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --body: 'Inter Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  /* Framing offsets read by stage.js on resize (1440 x 900 design shape). */
  --frame-x: 0.21;
  --frame-y: -0.02;
  --frame-fit: 1.08;
  color-scheme: dark;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: 15px;
  line-height: 1.52;
  -webkit-font-smoothing: antialiased;
}

body { overflow-x: clip; }

a { color: inherit; text-decoration: none; }
a:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }

code, pre, .mono {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
}

/* Fixed top instrument bar */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  background: rgba(13, 15, 18, 0.94);
  border-bottom: 1px solid var(--grid);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 48px;
  padding: 0 3.5vw;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--sans);
  font-weight: 700;
  letter-spacing: 0.1em;
  font-size: 0.85rem;
}

.brand-mark { display: block; flex-shrink: 0; }

.brand-ver {
  font-family: var(--mono);
  font-size: 0.72rem;
  font-weight: 400;
  color: var(--amber);
  border: 1px solid var(--amber-dim);
  padding: 0.08rem 0.38rem;
  letter-spacing: 0.04em;
}

.chapter-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.chapter-nav a {
  font-family: var(--mono);
  font-size: 0.72rem;
  color: var(--muted);
  padding: 0.28rem 0.48rem;
  border: 1px solid transparent;
  transition: color 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}

.chapter-nav a:hover { color: var(--ink); border-color: var(--grid); }
.chapter-nav a.is-active {
  color: var(--bg);
  background: var(--amber);
  border-color: var(--amber);
  font-weight: 600;
}

.docs-link {
  font-family: var(--mono);
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  color: var(--ink);
  border: 1px solid var(--grid);
  padding: 0.3rem 0.68rem;
  transition: border-color 0.15s ease, color 0.15s ease;
}

.docs-link:hover { border-color: var(--blue); color: var(--blue); }

.progress-rail {
  height: 2px;
  background: var(--surface2);
  width: 100%;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: var(--blue);
  transform-origin: left center;
}

/* 3D canvas */
#stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  height: 100lvh;
  display: block;
  z-index: 0;
}

.chapter { position: relative; z-index: 1; }

/* Film layout: active only once WebGL boots (.webgl-on) */
.webgl-on .chapter { min-height: 220vh; }
.webgl-on .chapter:first-child { min-height: 185vh; }
.webgl-on .chapter[data-chapter="flood"] { min-height: 250vh; }
.webgl-on .chapter[data-chapter="start"] { min-height: 200vh; }

.webgl-on .panel {
  position: fixed;
  top: 76px;
  left: 3.5vw;
  width: min(31rem, 36vw);
  max-height: calc(100vh - 104px);
