// props.js: the three open-mechanism instrument stations of Straitjacket along one machined bench.
// Stand-ins hold their places while modelling runs; once install_into_project installs each prop,
// `asset` and `module` load the real delivered GLB with LODs and compressed textures.
import * as THREE from 'three';

export const PROPS = {
  containment_press: { at: [0.0, 0, 0.0], turn: 0, size: [2.0, 1.8, 1.4] },
  evidence_vault: { at: [3.8, 0, 0.0], turn: 0, size: [1.6, 1.4, 1.3] },
  anchor_manifold: { at: [7.6, 0, 0.0], turn: 0, size: [2.2, 1.5, 1.5] },
};

const pascal = (s) => s.split('_').filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join('');

export function standIn([w, h, d]) {
  const geo = new THREE.BoxGeometry(w, h, d);
  geo.translate(0, h / 2, 0);
  const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0x3b414c, roughness: 0.65, metalness: 0.25 }));
  mesh.name = 'stand-in';
  const group = new THREE.Group();
  group.add(mesh);
  return group;
}

export async function loadProp(entry, renderer) {
  if (!entry.module) return standIn(entry.size);
  const mod = await entry.module();
  const load = mod['load' + pascal(entry.asset)];
  if (typeof load !== 'function') throw new Error(`${entry.asset}: its loader has no export load${pascal(entry.asset)}`);
  return load({ renderer, baseUrl: new URL(`agy3d/${entry.asset}/`, document.baseURI).href, collision: false });
}

// shots.js: pure function of story time T for Straitjacket's six-chapter visual journey.
// Every neighbouring chapter differs in shot scale (wide -> low -> medium -> close -> top -> low wide group)
// and by 44-86 degrees in viewing angle.

export const MOVE = 0.35;
export const REST = 0.7;

export const DESIGN_ASPECT = 1.6;
export const DESIGN_FREE = 0.6;

export const SHOT = {
  wide: { fill: 0.42, elevation: 16, fov: 34, push: 0.1, orbit: 8 },
  medium: { fill: 0.62, elevation: 22, fov: 30, push: 0.12, orbit: 7 },
  close: { fill: 0.76, elevation: 28, fov: 22, push: 0.08, orbit: 6 },
  top: { fill: 0.68, elevation: 72, fov: 30, push: 0.1, orbit: 12 },
  low: { fill: 0.62, elevation: 6, fov: 38, push: 0.08, orbit: 14 },
};

export function frame({ center, radius }, type = 'medium', { azimuth = 35, aspect = 1, ...options } = {}) {
  if (!SHOT[type]) throw new Error(`frame(): no shot type "${type}" (${Object.keys(SHOT).join(', ')})`);
  const { fill, elevation, fov, push, orbit } = { ...SHOT[type], ...options };
  const t = Math.tan((fov * Math.PI) / 360);
  const d = radius / (t * Math.min(1, aspect) * fill);
  const az = (azimuth * Math.PI) / 180, el = (elevation * Math.PI) / 180;
  const pos = [
    center[0] + d * Math.cos(el) * Math.sin(az),
    center[1] + d * Math.sin(el),
    center[2] + d * Math.cos(el) * Math.cos(az),
  ];
  return { pos, target: [...center], fov, push, orbit };
}

export function around(min, max) {
  const center = min.map((v, j) => (v + max[j]) / 2);
  return { center, radius: Math.hypot(...min.map((v, j) => max[j] - v)) / 2 };
}

// World bounding volumes for each chapter's focal mechanism and the full instrument line.
const LINE = around([-1.6, 0, -0.9], [8.9, 1.85, 1.0]);
const FLOOD_ZONE = around([-2.35, 0, -0.75], [1.65, 1.85, 0.75]);
const VAULT_ZONE = around([2.95, 0, -0.75], [4.75, 1.65, 1.05]);
const ANCHOR_ZONE = around([5.75, 0.05, 0.25], [6.65, 1.35, 1.15]);
const MANIFOLD_ZONE = around([6.45, 0, -0.8], [8.75, 1.55, 0.8]);

export const SHOTS = {
  // 01: Wide establishing of the full three-station Straitjacket bench
  intro: {
    ...frame(LINE, 'wide', { azimuth: 28, elevation: 18, fov: 34, fill: 0.62, push: 0.12, orbit: 7 }),
    span: 16,
    subject: ['containment_press', 'evidence_vault', 'anchor_manifold'],
  },
  // 02: Dramatic low angle into the Containment Press throat (6,053 red flood -> 11 blue digest + 1 amber needle)
