    span: 6.5,
    via: { pos: [2.2, 2.3, 4.4], target: [2.0, 0.8, 0.1] },
    subject: ['evidence_vault', 'vault_slice'],
  },
  // 04: Close-up telephoto shot of the Anchor Caliper tracking relocated source lines vs. stale unanchored drift
  anchors: {
