args.ReplacementContent:
.host-list li:last-child { grid-column: 1 / -1; }
.host-list li img { display: block; flex-shrink: 0; }
.host-list li span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.host-list li em {
  font-style: normal;
  font-family: var(--mono);
  font-size: 0.62rem;
  white-space: nowrap;
}
.gate-blue { color: var(--blue); }
.gate-amber { color: var(--amber); }

/* Actions */
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.9rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.5rem 0.85rem;
  font-family: var(--mono);
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  border: 1px solid var(--grid);
  border-radius: 0;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
  background: var(--amber);
  color: var(--bg);
  border-color: var(--amber);
  font-weight: 600;
}
.btn-primary:hover { background: var(--ink); border-color: var(--ink); }

.btn-ghost {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--grid);
}
.btn-ghost:hover { border-color: var(--blue); color: var(--blue); }

.receipt-foot {
  margin: 0.65rem 0 0 !important;
  padding-top: 0.5rem;
  border-top: 1px solid var(--grid);
  font-family: var(--mono);
  font-size: 0.68rem;
  color: var(--muted) !important;
}

.receipt-foot a { color: var(--blue); text-decoration: underline; text-underline-offset: 2px; }

/* Portrait phone layout: scene in upper half, compact instrument panel below */
@media (max-width: 899px) and (orientation: portrait) {
  :root {
    --frame-x: 0;
    --frame-y: 0.18;
    --frame-fit: 1;
    --frame-stack: 1;
  }

  .topbar-inner { height: 44px; padding: 0 12px; gap: 0.5rem; }
  .brand-name { font-size: 0.78rem; }
  .brand-ver { display: none; }
  .chapter-nav { gap: 0.1rem; }
  .chapter-nav a { padding: 0.22rem 0.32rem; font-size: 0.68rem; }
  .docs-link { padding: 0.22rem 0.48rem; font-size: 0.68rem; }

  .webgl-on .panel {
    top: auto;
    left: 10px;
    right: 10px;
    bottom: 10px;
    width: auto;
    max-height: 45vh;
    padding: 0.78rem 0.9rem;
  }

  .kicker { font-size: 0.64rem; margin-bottom: 0.34rem; }
  h1 { font-size: 1.24rem; margin-bottom: 0.34rem; }
  h2 { font-size: 1.08rem; margin-bottom: 0.32rem; }
  .panel p { font-size: 0.80rem; line-height: 1.40; margin-bottom: 0.42rem; }
  .legend-strip { margin: 0.44rem 0; gap: 0.25rem; }
  .tag { font-size: 0.6rem; padding: 0.1rem 0.3rem; }
