  .metric { padding: 0.34rem 0.42rem; }
  .metric-val { font-size: 0.9rem; }
  .metric-label, .metric-unit { font-size: 0.58rem; }
  .specimen { margin: 0.42rem 0; padding: 0.42rem 0.54rem; font-size: 0.64rem; line-height: 1.36; }
